import sys

data = sys.stdin.read().split()
n = int(data[0])
vals = [int(x) for x in data[1:1 + n]]
a, b = int(data[1 + n]), int(data[2 + n])
ia = ib = -1
for i in range(n):
    if vals[i] == a:
        ia = i
    if vals[i] == b:
        ib = i
if ia == -1 or ib == -1 or ia > ib:
    print(' '.join(map(str, vals)))
else:
    out = []
    for i in range(n):
        if ia <= i <= ib:
            out.append(vals[ia + ib - i])
        else:
            out.append(vals[i])
    print(' '.join(map(str, out)))

